refentry.refsect1:
  &reftitle.examples;



    Esempio di trigger_error


     Vedere set_error_handler per un esempio più completo.



<?php
$password = $_POST['password'] ?? '';
if ($password === '') {
  trigger_error("L'uso di una password vuota non è sicuro", E_USER_WARNING);
}
$hash = password_hash($password, PASSWORD_DEFAULT);
?>
